example_item.example_item_data:
% Le premier enregistrement de la base d'arythmie, recupere et lu.
recording = ecglab.reference('mitdb/100');
recording.info.source

% Parcourir toute une base depuis ce qui est deja sur le disque.
names = ecglab.reference('list', 'Database', 'mitdb');
for index = 1:numel(names)
  recording = ecglab.reference(['mitdb/', names{index}], 'Download', false);
end
